sp_page.css:
/* PAGE */

body,
.sp-page-root,
.container,
.container-fluid{

background:
linear-gradient(
180deg,
#F3F6FB 0%,
#EDF2F8 100%
);

margin:0 !important;

padding:0 !important;

max-width:100% !important;

overflow-x:hidden;

}



/* REMOVE SERVICE PORTAL GUTTERS */

.container-fluid{

padding-left:0 !important;

padding-right:0 !important;

}



/* ROW */

.sp-row{

margin:0 !important;

padding:0 !important;

}



/* COLUMN */

.sp-column{

padding-left:14px !important;

padding-right:14px !important;

}



/* WIDGET */

.sp-widget{

margin:0 !important;

padding:0 !important;

}



/* REMOVE PANEL GAP */

.panel,
.panel-default,
.panel-body{

margin:0 !important;

padding:0 !important;

border:none !important;

box-shadow:none !important;

background:transparent !important;

}



/* ===== REAL FIX ===== */
/* gap between widgets inside same column */

.sp-column > .sp-widget{

margin-bottom:24px !important;

}



/* remove gap after last widget */

.sp-column > .sp-widget:last-child{

margin-bottom:0 !important;

}



/* MOBILE */

@media(max-width:900px){

.sp-column{

padding-left:10px !important;

padding-right:10px !important;

}

.sp-column > .sp-widget{

margin-bottom:18px !important;

}

}
